import Foundation

/// One of a video's caption tracks, as the worker's resolve lists them.
public struct SubtitleTrack: Sendable, Codable, Hashable {
    /// BCP 47, e.g. "en" or "pt-BR".
    public var lang: String
    /// As YouTube names it, e.g. "English" or "English (United Kingdom)".
    public var name: String
    /// YouTube's timedtext address, in json3.
    public var url: URL
    /// Generated by speech recognition rather than uploaded.
    public var auto: Bool

    public init(lang: String, name: String, url: URL, auto: Bool) {
        self.lang = lang
        self.name = name
        self.url = url
        self.auto = auto
    }

    /// What the menu shows.
    public var title: String { auto ? "\(name) (auto-generated)" : name }

    /// yt-dlp-controlled strings: only YouTube's own caption endpoint is fetched.
    public var isAcceptable: Bool {
        url.scheme == "https" && url.host == "www.youtube.com" && url.path == "/api/timedtext"
    }
}

/// One of a video's audio languages (a dub or described audio), listed only when there are several.
public struct AudioTrack: Sendable, Codable, Hashable {
    public var lang: String
    /// As YouTube names it, e.g. "English (US) original" or "French".
    public var name: String
    public var url: URL
    /// The track the video plays by default.
    public var original: Bool

    public init(lang: String, name: String, url: URL, original: Bool) {
        self.lang = lang
        self.name = name
        self.url = url
        self.original = original
    }
}

public enum TrackChoice {
    /// The primary language of a tag: "pt" for "pt-BR".
    static func base(_ lang: String) -> Substring { lang.prefix { $0 != "-" && $0 != "_" } }

    /// The caption track for a remembered language: that exact one, else another variant of the language; an
    /// uploaded track before an auto-generated one. Nil when the video has none in it.
    public static func subtitles(_ tracks: [SubtitleTrack], preferred lang: String) -> SubtitleTrack? {
        guard !lang.isEmpty else { return nil }
        func rank(_ t: SubtitleTrack) -> Int? {
            let exact = t.lang.caseInsensitiveCompare(lang) == .orderedSame
            guard exact || base(t.lang).caseInsensitiveCompare(base(lang)) == .orderedSame else { return nil }
            return (t.auto ? 2 : 0) + (exact ? 0 : 1)
        }
        return tracks.enumerated().compactMap { i, t in rank(t).map { (rank: $0, index: i, track: t) } }
            .min { ($0.rank, $0.index) < ($1.rank, $1.index) }?.track
    }

    /// A resolve's caption tracks plus the saved ones it doesn't list (a track is its language and whether it's
    /// auto-generated; the URLs differ between resolves).
    public static func merged(_ resolved: [SubtitleTrack], saved: [SubtitleTrack]) -> [SubtitleTrack] {
        resolved + saved.filter { s in !resolved.contains { $0.lang == s.lang && $0.auto == s.auto } }
    }

    /// The audio track for a remembered language (exact, else a variant of it), or the default one.
    public static func audio(_ tracks: [AudioTrack], preferred lang: String) -> AudioTrack? {
        if !lang.isEmpty {
            if let exact = tracks.first(where: { $0.lang.caseInsensitiveCompare(lang) == .orderedSame }) { return exact }
            if let variant = tracks.first(where: { base($0.lang).caseInsensitiveCompare(base(lang)) == .orderedSame }) { return variant }
        }
        return tracks.first(where: \.original) ?? tracks.first
    }
}

public extension Resolved {
    /// The same streams with another audio language; unchanged when `track` is the one already playing.
    func playing(_ track: AudioTrack?) -> Resolved {
        guard let track, audioURL != nil, track.url != audioURL else { return self }
        var r = self
        r.audioURL = track.url
        return r
    }
}
